import java.util.*;public class ListBenchmark{static long time(Runnable r){long s=System.nanoTime();r.run();return System.nanoTime()-s;}public static void main(String[]x){int n=x.length==0?10000:Integer.parseInt(x[0]);List<Integer>a=new ArrayList<>(),l=new LinkedList<>();for(int i=0;i<n;i++){a.add(i);l.add(i);}System.out.println("ArrayList middle get ns "+time(()->{for(int i=0;i<1000;i++)a.get(n/2);}));System.out.println("LinkedList middle get ns "+time(()->{for(int i=0;i<1000;i++)l.get(n/2);}));System.out.println("ArrayList front insert ns "+time(()->a.add(0,-1)));System.out.println("LinkedList front insert ns "+time(()->l.add(0,-1)));Deque<Integer>d=new ArrayDeque<>();System.out.println("ArrayDeque end ops ns "+time(()->{for(int i=0;i<n;i++)d.addLast(i);while(!d.isEmpty())d.removeFirst();}));}}